/*
 * Study: run the 1x1 Conv example on the Ethos-U85 by programming the registers directly.
 *
 * What the CPU does here is all a "driver" is:
 *   1. place the Vela output in memory           (command stream, const = weights+bias/scale, arena = IFM+OFM)
 *   2. APB register writes                       (BASEPn = region addresses, QBASE/QSIZE = command stream)
 *   3. CMD = 1, wait for the IRQ                 (CC fetches the commands through DMA and runs them)
 *   4. read the OFM back from memory, and the PMU counters
 *
 * Data: conv1x1_data.h, generated by host/container/make_conv1x1_study.py (Vela log: study/conv1x1/).
 * Build: make -f Makefile.study [EVENT_SET=1|2]   (container, /work/selftest). NPU registers, PMU and timing
 * adapters through common/ (npu.h, npu_pmu.c, ta.c), the same code the measurement runner uses.
 *
 * TA state: profile 1 (MLEK ta_config_u85_sys_dram_mid), written and read back below; printed with the counters.
 * Memory: the vendor test3 layout (sections .ddr / .sec_noinit at 0x9000_0000), all regions on the AXI SRAM port.
 */
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "ARMCM85.h"
#include "Driver_USART.h"
#include "interface.h"
#include "npu.h"
#include "npu_pmu.h"
#include "serial.h"
#include "ta.h"

#include "conv1x1_data.h"

#define NPU_CMD_START     0x1U         /* CMD bit 0: transition to running */
#define NPU_CMD_CLEAR_IRQ 0x2U         /* CMD bit 1 */
#define IRQ_WAIT_LOOPS    10000000U

#ifndef EVENT_SET
#define EVENT_SET 1
#endif

extern ARM_DRIVER_USART Driver_USART0;

/* region 1 = arena: IFM at CONV1X1_IFM_OFFSET, OFM at CONV1X1_OFM_OFFSET (vendor test3 scratch section) */
__attribute__((section(".bss.sec_scratch_buffer"), aligned(16))) static uint8_t arena[CONV1X1_ARENA_BYTES];

static volatile uint32_t irq_seen;
static volatile uint32_t irq_status;

static void npu_irq_handler(void)
{
    irq_status = npu_read(NPU_REG_STATUS);
    npu_write(NPU_REG_CMD, NPU_CMD_CLEAR_IRQ);
    irq_seen = 1U;
}

/* ---- PMU: 8 event counters (names: docs/reference/trm_events_110.json, driver_events_171.json) ---- */
struct pmu_event { uint32_t id; const char *name; };
#if EVENT_SET == 1
/* which units worked: TRM events */
static const struct pmu_event events[8] = {
    {35, "npu_active"}, {48, "mac_active"}, {51, "mac_dpu_active"}, {64, "ao_active"},
    {80, "wd_active"}, {81, "wd_stalled"}, {130, "sram_rd_data_beat_received"}, {135, "sram_wr_data_beat_written"}};
#else
/* which buffer held a unit back: driver-only events (TRM Reserved), auxiliary evidence only */
static const struct pmu_event events[8] = {
    {55, "mac_stalled_by_ib"}, {53, "mac_stalled_by_w"}, {54, "mac_stalled_by_acc"}, {83, "wd_stalled_by_wd_buf"},
    {71, "ao_stalled_by_ab"}, {72, "ao_stalled_by_cb"}, {68, "ao_stalled_by_bs"}, {69, "ao_stalled_by_ob"}};
#endif

static void pmu_start(void)
{
    pmu_reg_write(NPU_REG_PMCNTENCLR, 0xFFFFFFFFU);
    pmu_reg_write(NPU_REG_PMOVSCLR, 0xFFFFFFFFU);
    for (uint32_t i = 0U; i < 8U; i++) {
        pmu_reg_write(NPU_REG_PMEVTYPER_BASE + 4U * i, events[i].id);
    }
    pmu_reg_write(NPU_REG_PMCR, NPU_PMCR_CNT_EN_MSK | NPU_PMCR_EVENT_CNT_RST_MSK | NPU_PMCR_CYCLE_CNT_RST_MSK);
    pmu_reg_write(NPU_REG_PMCNTENSET, 0xFFU);
}

static void pmu_report(void)
{
    pmu_reg_write(NPU_REG_PMCR, pmu_reg_read(NPU_REG_PMCR) & ~NPU_PMCR_CNT_EN_MSK);
    uint32_t ovf = pmu_reg_read(NPU_REG_PMOVSSET);
    printf("PMU event set %d (TA profile 1)%s\r\n", EVENT_SET, ovf ? "  OVERFLOW" : "");
    for (uint32_t i = 0U; i < 8U; i++) {
        printf("  %3lu %-28s %lu\r\n", (unsigned long)events[i].id, events[i].name,
               (unsigned long)pmu_reg_read(NPU_REG_PMEVCNTR_BASE + 4U * i));
    }
}

/* ---- the run: steps 1-4 of the header comment ---- */
static void npu_setup(void)
{
    /* AXI limits as the vendor test (256 B bursts); every region and the command stream through MEM_ATTR0 */
    npu_write(NPU_REG_AXI_SRAM, 0x00021F3FU);
    npu_write(NPU_REG_AXI_EXT, 0x00021F3FU);
    npu_write(NPU_REG_MEM_ATTR0, 0x0U);   /* bit 2 = 0: AXI SRAM port */
    npu_write(NPU_REG_REGIONCFG, 0x0U);   /* 2 bits per region -> MEM_ATTR index */
    npu_write(NPU_REG_QCONFIG, 0x0U);     /* command stream -> MEM_ATTR0 */

    npu_write(NPU_REG_BASEP0_LSB, (uint32_t)(uintptr_t)conv1x1_const);  /* region 0: weights (WD), bias/scale (AO) */
    npu_write(NPU_REG_BASEP0_MSB, 0U);
    npu_write(NPU_REG_BASEP1_LSB, (uint32_t)(uintptr_t)arena);          /* region 1: IFM (IB) and OFM (OB) */
    npu_write(NPU_REG_BASEP1_MSB, 0U);
    npu_write(NPU_REG_BASEP2_LSB, 0U);                                  /* region 2: fast scratch, unused (0 B) */
    npu_write(NPU_REG_BASEP2_MSB, 0U);

    npu_write(NPU_REG_QBASE_LSB, (uint32_t)(uintptr_t)conv1x1_cms);     /* command stream (CC via DMA) */
    npu_write(NPU_REG_QBASE_MSB, 0U);
    npu_write(NPU_REG_QSIZE, CONV1X1_CMS_BYTES);
}

static int check_ofm(void)
{
    const int8_t *ofm = (const int8_t *)&arena[CONV1X1_OFM_OFFSET];
    int bad = 0;
    printf("OFM (h,w): [oc0, oc1]  expected  acc\r\n");
    for (uint32_t p = 0U; p < 16U; p++) {
        int8_t o0 = ofm[2U * p], o1 = ofm[2U * p + 1U];
        int ok = (o0 == conv1x1_expected_ofm[2U * p]) && (o1 == conv1x1_expected_ofm[2U * p + 1U]);
        bad |= !ok;
        printf("  (%lu,%lu): [%4d,%4d]  [%4d,%4d]  [%4ld,%4ld] %s\r\n", (unsigned long)(p / 4U), (unsigned long)(p % 4U),
               o0, o1, conv1x1_expected_ofm[2U * p], conv1x1_expected_ofm[2U * p + 1U],
               (long)conv1x1_expected_acc[2U * p], (long)conv1x1_expected_acc[2U * p + 1U], ok ? "" : "<-- MISMATCH");
    }
    return bad;
}

int main(void)
{
    serial_init(&Driver_USART0, 115200);
    printf("\r\n=== study conv1x1: IFM 1x4x4x4 -> 1x1 conv -> OFM 1x4x4x2 ===\r\n");
    printf("NPU ID 0x%08lx CONFIG 0x%08lx\r\n", (unsigned long)npu_read(NPU_REG_ID), (unsigned long)npu_read(NPU_REG_CONFIG));

    if (ta_apply(1U) != 0U) {   /* common/ta.c, profile 1 = MLEK sys_dram_mid */
        printf("TA profile 1 NOT applied (version or read-back mismatch): result has no fixed TA state\r\n");
    }

    /* step 1: memory. IFM is copied into the arena where Vela allocated it; OFM poisoned so a no-op shows */
    memset(arena, 0xA5, sizeof(arena));
    memcpy(&arena[CONV1X1_IFM_OFFSET], conv1x1_ifm, CONV1X1_IFM_BYTES);
    __DSB();

    /* step 2: registers */
    npu_setup();
    printf("QBASE 0x%08lx (%u B)  BASEP0 const 0x%08lx  BASEP1 arena 0x%08lx\r\n",
           (unsigned long)(uintptr_t)conv1x1_cms, CONV1X1_CMS_BYTES,
           (unsigned long)(uintptr_t)conv1x1_const, (unsigned long)(uintptr_t)arena);

    /* step 3: start and wait for the IRQ */
    NVIC_SetVector(NPU0_IRQn, (uint32_t)(uintptr_t)&npu_irq_handler);
    NVIC_EnableIRQ(NPU0_IRQn);
    irq_seen = 0U;
    pmu_start();
    npu_write(NPU_REG_CMD, NPU_CMD_START);
    for (uint32_t i = 0U; i < IRQ_WAIT_LOOPS && !irq_seen; i++) {
    }

    /* step 4: results */
    uint32_t qread = npu_read(NPU_REG_QREAD);
    printf("IRQ %s, STATUS 0x%08lx, QREAD %lu / QSIZE %u\r\n", irq_seen ? "seen" : "TIMEOUT",
           (unsigned long)irq_status, (unsigned long)qread, CONV1X1_CMS_BYTES);
    pmu_report();
    int bad = check_ofm();
    printf("RESULT %s\r\n", (irq_seen && qread == CONV1X1_CMS_BYTES && !bad) ? "PASS" : "FAIL");

    while (1) {
    }
}
